"""Question-specific drafting tasks, never legal facts or test expectations."""
import re
from response_guidance import is_document_request


def practical_response_focus(question, previous=''):
    """Task guidance only: never additional facts, law or an acceptance gate."""
    current = question.split('\nПредыдущий вопрос:')[0]
    context = current + '\n' + (previous or '')
    if is_document_request(current):
        return ('Сразу дай редактируемый текст по текущей просьбе. Сохрани адресата и тему из контекста, '
                'неизвестные сведения оставь заполнителями. После текста предложи только проверку полей и сохранение копии. '
                'Не заменяй письмо списком действий и не добавляй новые требования или сроки для убедительности.')
    from response_guidance import is_reference_question
    if is_reference_question(current):
        extra = (' По переданным определениям различи общее понятие гражданского договора и отдельные виды договоров; '
                 'не своди общее понятие только к подряду или только к услугам.') if re.search(r'\bгпх\b|гражданско[ -]правов',current,re.I) else ''
        return ('Объясни термин простыми словами через его смысл для пользователя. '
                'Дай прямой подтверждённый ответ и существенную оговорку; не превращай определение в инструкцию по спору. '
                'Пример допустим только без придуманных ставок, сроков и правил.' + extra)
    base = ('Начни с решения текущей задачи, а не с пересказа документов. Для каждого предлагаемого действия '
            'покажи, что именно запросить или проверить и какой результат поможет выбрать следующий шаг. '
            'Начинай организационные шаги глаголом. Не повторяй вопросы, на которые пользователь уже ответил. ')
    if re.search(r'кредит|за[её]м|банк',context,re.I) and re.search(r'сравн|уменьш.{0,30}плат[её]ж|продл.{0,25}срок',current,re.I):
        return base + ('Предложи сопоставить старый и новый графики, общую сумму выплат, срок и отдельные расходы. '
                       'Без этих данных не делай вывода о выгодности предложения; не ограничивай сравнение одним платежом.')
    if re.search(r'аренд|залог|обеспечительн',context,re.I) and re.search(r'удерж|не возвращ|причин',context,re.I):
        return base + ('Для первого шага предложи запросить причины и расчёт удержания по пунктам, '
                       'сопоставить их с договором, актами и подтверждениями оплаты. Не обещай возврат всей суммы.')
    if re.search(r'банк|карт',context,re.I) and re.search(r'списа|комисси|удерж|непонятн.{0,20}плат[её]ж',context,re.I):
        return base + ('Помоги подготовить запрос о конкретной операции: назначение списания, расчёт и строка тарифа. '
                       'Не утверждай заранее, что списание незаконно или что возврат гарантирован.')
    return base + ('Дай применимые действия и не более двух уточнений, которые действительно изменят дальнейший совет. '
                   'Если подтверждена только часть ответа, сохрани её и отдельно назови недостающую деталь.')


def drafting_focus(question, previous, evidence):
    current = question.split('\nПредыдущий вопрос:')[0]
    context = current + '\n' + (previous or '')
    documents = {p.get('document_id') for p in evidence}
    tasks = []
    if 'credit-history' in documents and re.search(r'кредитн.{0,20}(?:истори|отч[её]т)|бюро|погашенн.{0,20}(?:кредит|за[её]м)', context, re.I):
        if is_document_request(current):
            tasks.append('Подготовь само заявление о проверке спорной записи: Кому, От, какая запись оспаривается, что проверить/исправить, перечень подтверждений, Дата и Подпись. Используй заполнители вместо личных данных. Просьбы не выдавай за гарантированный результат; достоверную историю не обещай удалить.')
        elif re.search(r'ошиб|неверн|недостовер|исправ|оспор|погаш|закрыт|просроч', current, re.I):
            tasks.append('Раздели спорную запись и доказательства её ошибочности, адресата проверки — бюро или поставщика сведений по переданным нормам — и запрос письменного результата. Не обещай автоматическое исправление или удаление всей кредитной истории.')
        elif re.search(r'получ|узна|скача|заказ|посмотр', current, re.I):
            tasks.append('Ответь о получении отчёта о себе: предложи официальный канал бюро или государственной услуги без непроверенной ссылки, объясни безопасную проверку личности через этот канал. Не проси присылать пароль, код или полный отчёт в чат. Не добавляй спор об ошибке, если его не спрашивали.')
    if ('collectors' in documents and re.search(r'чуж|родственник|знаком', current, re.I)
            and not re.search(r'угроз|насили', current, re.I)):
        tasks.append('Раздели контакт с третьим лицом и требование оплатить долг. Предложи запросить основание требования и проверить, какую роль в договоре приписывают пользователю; не выводи его обязанность или её отсутствие только из родства.')
    if 'shared-construction' in documents and re.search(r'документ|провер|каки.{0,15}способ', current, re.I):
        tasks.append('Сопоставь запрошенные документы с конкретным способом привлечения денег, описанным в источниках. Различай сведения о гарантии и разрешение там, где они предусмотрены; не требуй одновременно одинаковый комплект для любых схем. Предложи запросить название компании и способ привлечения денег без перевода оплаты до проверки.')
    if 'auto-insurance' in documents and re.search(r'удерж|выч[её]л|вычет|оценк.{0,20}расход|расход.{0,20}оценк', current, re.I):
        tasks.append('Разбери именно удержание из выплаты: предложи запросить расчёт и название удержанных расходов. Отдели собственные расходы страховщика на определение ущерба от иных возможных платежей. Правовую оценку дай только по соответствующей переданной норме, не по общему описанию страхового случая.')
    if 'joint-stock' in documents and re.search(r'дивиденд|доход|распределен', current, re.I):
        tasks.append('Сначала установи вид акций: общее описание решения по выплате не переноси автоматически на привилегированные акции. Сохрани отдельно подтверждённые условия и ограничения из источников; не перечисляй ненужные числовые сроки.')
    if 'digital-assets' in documents and re.search(r'отлич|разниц|сравн|вид[ыа]', current, re.I):
        tasks.append('Дай сравнение названных категорий по определениям из переданной редакции. Если термин в вопросе и термин в действующем фрагменте различаются, обозначь это различие, не подменяя одну классификацию другой. Не обещай доходность, гарантии государства или разрешённость любой площадки.')
    if 'family' in documents:
        from retrieval_intents import child_residence_question
        if child_residence_question(current):
            tasks.append('Сначала ответь на вопрос, решает ли ребёнок всё сам. Раздели учёт мнения и определение места жительства: для каждого вывода выбери именно свой фрагмент статьи. Для вывода из двух положений укажи оба источника. Сохрани исключение об интересах ребёнка. Не добавляй возраст или процедуру, которых нет в переданных выдержках.')
    if 'collectors' in documents and re.search(r'угро|насили|удар|запуг|пуга', current, re.I):
        tasks.append('Начни с безопасных организационных действий отдельными строками: «Обеспечьте свою безопасность при непосредственной угрозе»; «Свяжитесь с экстренной службой через официальный канал»; «Сохраните сообщения и обстоятельства угроз». Далее объясни только подтверждённые ограничения взыскания. Не добавляй неподтверждённые сроки, телефоны или гарантии. Условие не превращай в утверждение, что угроза уже доказана.')
    if 'nb-phishing-loan' in documents:
        tasks.append('Когда вопрос относится к подозрительному извещению о займе, предложи «Не переходите по ссылке из сообщения» и назови официальные каналы проверки, указанные в переданной памятке. Отдели меры защиты от процедуры исправления кредитного отчёта. Не объявляй любое уведомление доказанным мошенничеством.')
    return tasks
